typedef struct {U32 cb;W type[17],device[129];} Device;
typedef struct {U32 cb;H h;W name[257],type[17],device[129],book[260];U32 sub;Guid id;U32 flags,luid[2];Guid cor;} Connection;
extern U32 RasGetEntryPropertiesW(T,T,Entry*,U32*,U8*,U32*),RasSetEntryPropertiesW(T,T,Entry*,U32,U8*,U32),RasValidateEntryNameW(T,T),RasEnumDevicesW(Device*,U32*,U32*),RasEnumConnectionsW(Connection*,U32*,U32*),RasDeleteEntryW(T,T);
static int l2tp(W*out){U32 bytes=0,n=0,e=RasEnumDevicesW(0,&bytes,&n);if((e&&e!=603)||bytes<sizeof(Device)||bytes>0x100000)return 0;Device*d=HeapAlloc(GetProcessHeap(),8,bytes);if(!d)return 0;d[0].cb=sizeof(*d);int ok=0;if(!RasEnumDevicesW(d,&bytes,&n))for(U32 i=0;i<n;i++)if(eq(d[i].type,L"vpn")){for(int j=0;d[i].device[j];j++)if((d[i].device[j]|32)=='l'&&d[i].device[j+1]=='2'&&(d[i].device[j+2]|32)=='t'&&(d[i].device[j+3]|32)=='p'){ok=cp(out,129,d[i].device);break;}if(ok)break;}HeapFree(GetProcessHeap(),0,d);return ok;}
int guidprofile(T p){if(sz(p)!=36||p[0]!='C'||p[1]!='Z'||p[2]!='5'||p[3]!='-')return 0;for(int i=4;i<36;i++)if(!((p[i]>='0'&&p[i]<='9')||(p[i]>='a'&&p[i]<='f')))return 0;return 1;}
int getprofile(W*out,int cap){return getstr(HKCU,CLIKEY,L"VPN",out,cap)&&guidprofile(out);}
static H findconn(T p){U32 bytes=sizeof(Connection),n=0;Connection local={0},*v=&local;local.cb=sizeof(local);U32 e=RasEnumConnectionsW(v,&bytes,&n);if(e==603&&bytes<=1<<20){v=HeapAlloc(GetProcessHeap(),8,bytes);if(!v)return 0;v->cb=sizeof(*v);e=RasEnumConnectionsW(v,&bytes,&n);}H h=0;if(!e)for(U32 i=0;i<n;i++)if(eq(p,v[i].name))h=v[i].h;if(v!=&local)HeapFree(GetProcessHeap(),0,v);return h;}
static int checkentry(T p,const Endpoint*ep){if(!guidprofile(p)||!validend(ep))return 0;U32 n=65536;Entry*e=HeapAlloc(GetProcessHeap(),8,n);if(!e)return 0;e->cb=sizeof(*e);int ok=!RasGetEntryPropertiesW(0,p,e,&n,0,0)&&e->kind==2&&e->strategy==3&&(e->opts2&16)&&e->enc==1&&eq(e->phone,ep->host)&&(e->opts&0x20000000)&&!(e->opts&(0x80000000u|0x08000000u|0x10000000u));HeapFree(GetProcessHeap(),0,e);return ok;}
int vpninstall(const Endpoint*ep,T who,W*pass,W*key,W*out,int cap){if(!validend(ep)||sz(ep->host)>128||!sz(who)||sz(who)>128||!sz(pass)||sz(pass)>127||!sz(key)||sz(key)>127){cp(out,cap,L"서버 주소와 공유기에 만든 VPN 아이디·암호·IPsec 공유 키를 확인하세요.");return 0;}W old[48];if(getprofile(old,CNT(old))){cp(out,cap,L"기존의 앱 전용 VPN이 있습니다. 먼저 ‘VPN 해제’를 선택하세요.");return 0;}W name[48]=L"CZ5-";if(!guidtext(name+4,40)||RasValidateEntryNameW(0,name))return errnum(out,cap,L"VPN 이름 생성 실패",GetLastError());Entry entry={0};entry.cb=sizeof(entry);entry.kind=2;entry.opts=0x20000000|0x1000;entry.opts2=0x80000|0x100|16|8;entry.net=4;entry.ppp=1;entry.enc=1;entry.strategy=3;entry.channels=1;entry.sub=1;entry.dmode=1;entry.retries=3;entry.delay=12;cp(entry.phone,129,ep->host);cp(entry.type,17,L"vpn");if(!l2tp(entry.device)){cp(out,cap,L"Windows 기본 L2TP 장치를 찾을 수 없습니다.");return 0;}U32 e=RasSetEntryPropertiesW(0,name,&entry,sizeof(entry),0,0);if(e)return errnum(out,cap,L"Windows VPN 생성 실패",e);RasCred c={0};c.size=sizeof(c);c.mask=16;cp(c.pass,CNT(c.pass),key);e=RasSetCredentialsW(0,name,&c,0);erase(&c,sizeof(c));if(!e){c.size=sizeof(c);c.mask=3;cp(c.user,CNT(c.user),who);cp(c.pass,CNT(c.pass),pass);e=RasSetCredentialsW(0,name,&c,0);erase(&c,sizeof(c));}W cmd[580],tmp[240];_snwprintf(cmd,CNT(cmd),L"Add-VpnConnectionRoute -ConnectionName '%ls' -DestinationPrefix '%ls/32' -RouteMetric 1 -ErrorAction Stop | Out-Null",name,ep->ip);if(!e&&!checkentry(name,ep))e=13;if(!e&&!cmdlet(cmd,tmp,CNT(tmp)))e=1168;if(!e&&!putstr(HKCU,CLIKEY,L"VPN",name))e=5;if(e){U32 roll=RasDeleteEntryW(0,name);return errnum(out,cap,roll?L"VPN 설정 실패. Windows에서 남은 CZ5 프로필을 확인하세요.":L"VPN을 등록하지 못해 이번 프로필을 제거했습니다.",e);}return cp(out,cap,L"Windows에 개인 VPN을 등록했습니다. 다음 단계는 ‘드라이브’입니다.");}
int route5(const Endpoint*ep,W*out,int cap){W pname[48];if(!getprofile(pname,CNT(pname))||!checkentry(pname,ep)||!findconn(pname))return 0;W cmd[750],buf[140];_snwprintf(cmd,CNT(cmd),L"$r=Find-NetRoute -RemoteIPAddress '%ls' | Where-Object { $_.DestinationPrefix }; if ($r.InterfaceAlias -eq '%ls' -and $r.DestinationPrefix -eq '%ls/32') { 'CZ5-ROUTE' }",ep->ip,pname,ep->ip);if(cmdlet(cmd,buf,CNT(buf))&&eq(buf,L"CZ5-ROUTE")){cp(out,cap,L"공유기 직접 VPN (앱 중계 없음)");return 1;}return 0;}
static int temporary;int transient5(void){return temporary;}
int connectnas(const Endpoint*ep,int home,W*out,int cap){temporary=0;if(!validend(ep))return 0;if(home){W cmd[600],b[140];_snwprintf(cmd,CNT(cmd),L"$r=Find-NetRoute -RemoteIPAddress '%ls' | Where-Object { $_.DestinationPrefix }; if ($r.NextHop -eq '0.0.0.0' -and (Get-NetConnectionProfile -InterfaceIndex $r.InterfaceIndex).NetworkCategory -eq 'Private') { 'CZ5-LAN' }",ep->ip);if(cmdlet(cmd,b,CNT(b))&&eq(b,L"CZ5-LAN"))return cp(out,cap,L"집 안 직접 연결");cp(out,cap,L"신뢰하는 개인망의 같은 LAN에서만 집 안 모드를 쓸 수 있습니다.");return 0;}
W name[48];if(!getprofile(name,CNT(name))||!checkentry(name,ep)){cp(out,cap,L"먼저 이 서버 주소에 맞는 ‘외부 VPN’을 등록하세요.");return 0;}if(route5(ep,out,cap))return 1;
if(!findconn(name)){RasCred c={0};c.size=sizeof(c);c.mask=3;U32 e=RasGetCredentialsW(0,name,&c);if(e||(c.mask&3)!=3){erase(&c,sizeof(c));return errnum(out,cap,L"Windows의 저장된 VPN 로그인을 찾지 못했습니다.",e);}RasParams a={0};a.size=sizeof(a);cp(a.entry,CNT(a.entry),name);cp(a.user,CNT(a.user),c.user);cp(a.pass,CNT(a.pass),c.pass);erase(&c,sizeof(c));H h=0;e=RasDialW(0,0,&a,0,0,&h);erase(&a,sizeof(a));if(e){temporary=(e==809||e==868||e==1231||e==638);if(h)RasHangUpW(h);return errnum(out,cap,L"공유기 VPN에 연결하지 못했습니다. 서버 설정·도메인·VPN 암호를 확인하세요.",e);}}
for(int i=0;i<4;i++){if(route5(ep,out,cap))return 1;Sleep(400);}cp(out,cap,L"지정한 PC까지 이 VPN을 경유하는지 확인할 수 없어 NAS 로그인을 전송하지 않았습니다.");return 0;}
int forgetvpn(W*out,int cap){W name[48];Endpoint ep;if(!getprofile(name,CNT(name))||!loadendpoint(HKCU,CLIKEY,&ep)||!checkentry(name,&ep)){cp(out,cap,L"이 앱이 만든 프로필을 확인하지 못했습니다.");return 0;}H h=findconn(name);if(h){U32 e=RasHangUpW(h);if(e)return errnum(out,cap,L"VPN 종료 실패",e);for(int i=0;i<25&&findconn(name);i++)Sleep(200);if(findconn(name)){cp(out,cap,L"VPN 종료 중입니다. 잠시 후 다시 선택하세요.");return 0;}}U32 e=RasDeleteEntryW(0,name);if(e)return errnum(out,cap,L"VPN 해제 실패",e);delstr(HKCU,CLIKEY,L"VPN");return cp(out,cap,L"이 앱의 Windows VPN 프로필을 제거했습니다.");}
